// requireReviewPass requires a D01 pass of the exact candidate: commit when
// given, otherwise the current Task branch tips.
func greenhouseAcceptHeadDisposition(ctx context.Context, db *store.DB, task store.Task, head string) (bool, error) {
	var accepted bool
	err := db.QueryRowContext(ctx, `SELECT EXISTS(
SELECT 1 FROM review_dispositions rd JOIN decisions d ON d.id=rd.decision_id
WHERE rd.ship_task_id=? AND rd.head_sha=? AND d.task_id=? AND d.kind='review_cap' AND d.answer='accept-head' AND d.answered_at>0 AND d.obsolete_at=0
)`, task.ID, head, task.ID).Scan(&accepted)
	return accepted, err
}

func requireGreenhouseGatePass(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, task store.Task, commit, repository string) error {
	var targets []store.ReviewTarget
	var err error
	if greenhouseFullPipelineTaskWithConfig(task, cfg, "") && !project.IsWorkspace() {
		head, err := gitOutput(ctx, task.WorktreePath, "rev-parse", "HEAD")
		if err != nil {
			return err
		}
		targets = []store.ReviewTarget{{Repository: project.Name, Commit: head}}
	} else {
		targets, err = changeCandidateTargets(ctx, db, project, task)
		if err != nil {
			return err
		}
	}
	if repository != "" {
		filtered := targets[:0]
		for _, target := range targets {
			if target.Repository == repository {
				if commit != "" {
					target.Commit = commit
				}
				filtered = append(filtered, target)
			}
		}
		targets = filtered
	} else if !project.IsWorkspace() && commit != "" {
		targets = []store.ReviewTarget{{Repository: project.Name, Commit: commit}}
	}
	for _, target := range targets {
		passed, err := db.GreenhouseGatePass(ctx, task.ID, target.Repository, target.Commit)
		if err != nil {
			return err
		}
		if !passed {
			accepted, err := greenhouseAcceptHeadDisposition(ctx, db, task, target.Commit)
			if err != nil {
				return err
			}
			if accepted {
				continue
			}
			return axi.Failure("greenhouse_verdict_required", "Task "+taskIDString(task.Seq)+" has no current passing Greenhouse Verdict or exact-head acceptance for "+target.Repository+" at "+shortSHA(target.Commit), false, "Wait for the Greenhouse Verdict or apply the exact-head review-cap acceptance before publication or Merge")
		}
	}
	return nil
}

func requireReviewPass(ctx context.Context, db *store.DB, project store.Project, change store.Task, commit string) error {
	var targets []store.ReviewTarget
	var err error
	if commit == "" {
		targets, err = changeCandidateTargets(ctx, db, project, change)
	} else {
		targets = []store.ReviewTarget{{Repository: project.Name, Commit: commit}}
	}
	if err != nil {
		return err
	}
	evidence, err := db.ReviewEvidenceFor(ctx, change.ID, targets)
	if err != nil {
		return err
	}
	if !evidence.Complete {
		if err := ensureReviewCarry(ctx, db, project, change, targets); err != nil {
			return err
		}
		evidence, err = db.ReviewEvidenceFor(ctx, change.ID, targets)
		if err != nil {
			return err
		}
	}
	if evidence.Complete {
		return nil
	}
	id := taskIDString(change.Seq)
	revision := "its current revision"
	if commit != "" {
		revision = "candidate " + shortSHA(commit)
	}
	help := "Dispatch a Review Task for " + id + " with `review_of: " + id + "` and wait for a `pass` verdict; only an explicit User choice may select lighter review"
	if plan, err := change.AdmittedPlan(); err == nil && requireFrozenReviewLoop(plan) == nil {
		help = "Run `posse review start " + id + " --profile <profile>` and wait for a `pass` verdict; only an explicit User choice may select lighter review"
	}
	return axi.Failure("review_required", "Task "+id+" has no passing Review, proved carry, or exact-head User disposition for "+revision, false, help)
}

