	parts := strings.Split(origin, ":")
	if (len(parts) != 3 && (len(parts) != 5 || parts[3] != "recovery" || parts[4] == "")) || parts[0] != "review_cap" || !strings.HasPrefix(parts[1], "t") || len(parts[2]) != 40 && len(parts[2]) != 64 {
