	if err := json.Unmarshal([]byte(notice.DataJSON), &data); err != nil {
		return reviewCapBinding{}, 0, 0, err
	}
	if data.Head == "" || data.Used < 1 || data.Max < 1 {
		return reviewCapBinding{}, 0, 0, fmt.Errorf("invalid Review cap Notice")
